const alert = $input.first().json;
return [{ json: {
  channel: 'SLACK_OPERATIONS',
  urgency: 'HIGH',
  message: `⚠️ [${alert.severity || 'CRITICAL'}] ${alert.title || 'Door Hydraulic Outage'}: ${alert.description || 'Immediate hostler divert dispatched.'}`,
  dispatched_at: new Date().toISOString()
}}];

// Log workflow execution audit
const res = $input.all();
return res.map(r => ({ json: { ...r.json, _audit: { workflow: '12 - Real-Time Alerts and Notifications', processed_at: new Date().toISOString() } } }));
